UPDATE collector_source_cursor SET current_record_id = #{recordId}, current_version = #{version},
    current_fingerprint = #{fingerprint}, source_updated_at = #{sourceUpdatedAt}
WHERE identity_hash = #{identity}

UPDATE collector_event_outbox SET status = 'LEASED', lease_token = #{token},
       lease_until = DATE_ADD(NOW(), INTERVAL 2 MINUTE), attempts = attempts + 1
WHERE id = #{id}

UPDATE collector_event_outbox SET status = 'PENDING', lease_token = NULL, lease_until = NULL,
       next_attempt_at = DATE_ADD(NOW(), INTERVAL 30 SECOND)
WHERE id = #{id} AND status = 'LEASED' AND lease_token = #{token}
